package add_table

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/generated/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "add_table"
	command.Identifiers = []string{"add-table"}
	command.Category = "Database System"
	command.Help = "Declare one collection of records on a database"
	command.LongDescription = "Appends one table to the database's specs.yaml and runs build. A table is born with no fields: what it holds is declared one 'agnos add-table-field' at a time, and every method the table generates is spelled after its name."
	command.Examples = []string{"add-table url --database app-database"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "database",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the database (identifier or package name) the table is declared on",
			Examples:    []string{"add-table url --database app-database"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--database"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the name of the new table (e.g. url)",
			Examples:    []string{"add-table url --database app-database"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
